BEGIN;
CREATE TABLE IF NOT EXISTS hr_high_impact_audit(id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,tenant_id TEXT,company_id TEXT,branch_id TEXT,entity_table TEXT NOT NULL,entity_id TEXT,operation TEXT NOT NULL CHECK(operation IN('INSERT','UPDATE','DELETE')),actor_id TEXT,request_id TEXT,before_value JSONB,after_value JSONB,changed_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS hr_high_impact_audit_tenant_time_idx ON hr_high_impact_audit(tenant_id,changed_at DESC);
CREATE INDEX IF NOT EXISTS hr_high_impact_audit_entity_idx ON hr_high_impact_audit(entity_table,entity_id,changed_at DESC);
CREATE OR REPLACE FUNCTION hr_capture_high_impact_audit() RETURNS trigger AS $$ DECLARE old_row JSONB;new_row JSONB;source JSONB;BEGIN old_row:=CASE WHEN TG_OP IN('UPDATE','DELETE')THEN to_jsonb(OLD)ELSE NULL END;new_row:=CASE WHEN TG_OP IN('INSERT','UPDATE')THEN to_jsonb(NEW)ELSE NULL END;source:=COALESCE(new_row,old_row,'{}'::jsonb);INSERT INTO hr_high_impact_audit(tenant_id,company_id,branch_id,entity_table,entity_id,operation,actor_id,request_id,before_value,after_value)VALUES(COALESCE(source->>'tenant_id',source->>'tenantId'),COALESCE(source->>'company_id',source->>'companyId'),COALESCE(source->>'branch_id',source->>'branchId'),TG_TABLE_NAME,source->>'id',TG_OP,NULLIF(current_setting('app.actor_id',true),''),NULLIF(current_setting('app.request_id',true),''),old_row,new_row);RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END;$$ LANGUAGE plpgsql;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['employee_master_records','hr_employee_assignments','leave_requests','hr_leave_entitlements','hr_leave_ledger','hr_approval_instances','hr_approval_actions','payroll_periods','payroll_items','salary_payments','hr_employee_compensation','hr_compensation_records','hr_employee_advances','hr_expense_claims','hr_cases','hr_case_actions','hr_employee_assets','hr_employment_contracts'] LOOP IF to_regclass(t) IS NOT NULL THEN EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I','audit_'||t,t);EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION hr_capture_high_impact_audit()','audit_'||t,t);END IF;END LOOP;END $$;
CREATE OR REPLACE FUNCTION hr_reject_audit_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'HR audit history is immutable' USING ERRCODE='55000';END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS hr_high_impact_audit_immutable ON hr_high_impact_audit;
CREATE TRIGGER hr_high_impact_audit_immutable BEFORE UPDATE OR DELETE ON hr_high_impact_audit FOR EACH ROW EXECUTE FUNCTION hr_reject_audit_mutation();
COMMIT;
